class Solution:
    def solve(self, n: int, end: int, edges: list, start: int) -> float:
        import heapq
        graph = [[] for _ in range(n)]
        for a, b, weight in edges:
            graph[a].append((b, weight))
            graph[b].append((a, weight))
        max_prob = [0.0] * n
        max_prob[start] = 1.0
        queue = [(-1.0, start)]
        while queue:
            prob, node = heapq.heappop(queue)
            for next_node, weight in graph[node]:
                new_prob = -prob * weight
                if new_prob > -max_prob[next_node]:
                    max_prob[next_node] = -new_prob
                    heapq.heappush(queue, (-max_prob[next_node], next_node))
        return max(0.0, min(1.0, max_prob[end]))
